examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchWeeklyHoursEditor(
        value = hours,
        onValueChange = { hours = it },
        firstDayOfWeek = 2,
        is24Hour = true,
        timeZoneLabel = { MonarchText(text = {{timeZoneLabel}}, style = MonarchTextStyle.Caption) },
    )
    // The total of the week, as the web shows under the editor.
    val total = hours.sumOf { it.end - it.start } / 60.0
    MonarchText(
        text = "%s hours a week".format(if (total % 1.0 == 0.0) total.toInt().toString() else total.toString()),
        style = MonarchTextStyle.Caption,
        color = MonarchTheme.colors.textMuted,
    )
}

examples.setupTemplate:
var hours by remember {
    mutableStateOf(
        listOf({{days.0}}, {{days.1}}, {{days.2}}, {{days.3}}, {{days.4}}).flatMap { day ->
            listOf(
                MonarchWeeklyHoursInterval(day = day, start = {{intervals.0.start}}, end = {{intervals.0.end}}),
                MonarchWeeklyHoursInterval(day = day, start = {{intervals.1.start}}, end = {{intervals.1.end}}),
            )
        },
    )
}

